480	func TestOrganizationsChainsAreIndependent(t *testing.T) {
481		s := NewStore()
482		// Identical policy and subject identifiers in two organizations.
483		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
484		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
485		s.Publish("globex", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
486		s.Decide("globex", request("globex", "u1", "r1", "org/a", "read"))
487	
488		a, acp, _ := s.AuditExport("acme", 0)
489		g, gcp, _ := s.AuditExport("globex", 0)
490		if err := VerifyAudit("acme", a, acp); err != nil {
491			t.Fatal(err)
492		}
493		if err := VerifyAudit("globex", g, gcp); err != nil {
494			t.Fatal(err)
495		}
496		// Same sequence numbers, different fingerprints.
497		if a[0].Fingerprint == g[0].Fingerprint || a[1].Fingerprint == g[1].Fingerprint {
498			t.Fatal("organizations share fingerprints despite org-bound genesis")
499		}
500		// A globex record spliced into the acme chain must fail.
501		spliced := append([]AuditRecord(nil), a[0], g[1])
502		if err := VerifyAudit("acme", spliced, Checkpoint{
503			Org: "acme", EndSeq: 2, Fingerprint: spliced[1].Fingerprint,
504		}); err == nil {
505			t.Fatal("foreign-organization record verified in the acme chain")
506		}
507		// Whole globex export cannot verify under the acme name.
508		if err := VerifyAudit("acme", g, gcp); err == nil {
509			t.Fatal("globex export verified as acme")
510		}
511	}
