1	// This file pins down the independent-copy guarantee for the two lists
2	// embedded in an audited decision:
3	//
4	//   - Request.Subject.Roles — the subject's roles are part of the audited
5	//     request even though they take no part in organization policy
6	//     authorization, and their submitted order is historical fact.
7	//   - Decision.Matched — the complete matched-policy list is part of the
8	//     decision explanation an auditor must be able to reconstruct.
9	//
10	// The store promises to save its own detached copy when Decide is called
11	// and to hand out detached copies from audit query, paging, export,
12	// archive and recheck entry points. These tests exercise that promise
13	// through the public API only: after a decision the caller may rewrite or
14	// extend the request roles and matched list they hold, and after reading a
15	// record they may edit the same lists in every material they received;
16	// the stored history, a fresh read and a previously retained copy must all
17	// keep the decision-time content. A regression that aliases either list
18	// into caller memory fails here no matter which read path exposes it.
19	package darksafe
20	
21	import (
22		"errors"
23		"reflect"
24		"strings"
25		"testing"
26	)
27	
28	// listIsolationRoles is a non-empty role list exercising Chinese, leading,
29	// trailing and internal spaces, and a lone non-UTF-8 byte. Roles never
30	// authorize anything, so the decision is driven by policies while the
31	// roles survive purely as preserved request content.
32	func listIsolationRoles() []string {
33		return []string{"角色 alpha", "  前后 空格  ", "原" + invalidByte + "始"}
34	}
35	
36	// listIsolationPolicies gives u2 exactly one allow hit (whose id carries a
37	// non-UTF-8 byte) and u1 a deny hit together with allow hits, so the deny
38	// decision still carries a complete, ordered matched list.
39	func listIsolationPolicies() []Policy {
40		return []Policy{
41			{ID: "z-allow 许", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
42			{ID: "a-deny 拒", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectDeny},
43			{ID: "m-allow 中" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, Recursive: true},
44			{ID: "p-allow 通" + invalidByte, Subject: "u2", Action: "read", Scope: "org/a", Effect: EffectAllow},
45		}
46	}
47	
48	// roleRequest builds one legal request for the subject with the given
49	// roles, using a fresh backing array so each fixture request is independent.
50	func roleRequest(subject string, roles []string) OrgRequest {
51		req := request("acme", subject, "r1", "org/a", "read")
52		req.Subject.Roles = append([]string(nil), roles...)
53		return req
54	}
55	
56	// assertDecisionListContent checks the complete decision-time content the
57	// history must still show: role order, matched list, effect, reason and
58	// the version actually used.
59	func assertDecisionListContent(t *testing.T, r *AuditRecord, seq int, wantRoles []string, want Decision) {
60		t.Helper()
61		if r.Seq != seq || r.Kind != AuditDecision || r.Decision == nil {
62			t.Fatalf("seq %d: not a decision record: %+v", seq, r)
63		}
64		if got := r.Decision.Request.Subject.Roles; !reflect.DeepEqual(got, wantRoles) {
65			t.Fatalf("seq %d roles = %q, want decision-time %q", seq, got, wantRoles)
66		}
67		got := r.Decision.Decision
68		if got.Allowed != want.Allowed {
69			t.Fatalf("seq %d allowed = %v, want %v", seq, got.Allowed, want.Allowed)
70		}
71		if got.Reason != want.Reason {
72			t.Fatalf("seq %d reason = %q, want %q", seq, got.Reason, want.Reason)
73		}
74		if got.Version != want.Version {
75			t.Fatalf("seq %d version = %d, want %d", seq, got.Version, want.Version)
76		}
77		if !reflect.DeepEqual(got.Matched, want.Matched) {
78			t.Fatalf("seq %d matched = %q, want %q", seq, got.Matched, want.Matched)
79		}
80	}
81	
82	// recordBySeq returns the decision record at seq, failing the test when it
83	// is absent or not a decision.
84	func recordBySeq(t *testing.T, recs []AuditRecord, seq int) *AuditRecord {
85		t.Helper()
86		for i := range recs {
87			if recs[i].Seq == seq {
88				if recs[i].Kind != AuditDecision || recs[i].Decision == nil {
89					t.Fatalf("seq %d is not a decision", seq)
90				}
91				return &recs[i]
92			}
93		}
94		t.Fatalf("no record at seq %d among %d records", seq, len(recs))
95		return nil
96	}
97	
98	// TestDecideListCopiesSurviveCallerEdits covers the primary promise: once
99	// Decide returned, the caller may replace role names in the request they
100	// submitted, append roles, and rewrite or extend the matched policies in
101	// the decision they got back. Both an allow decision and a deny decision
102	// that carries matched policies must keep independent copies — not only
103	// the authorization success. Every later read (export, paged query,
104	// online and offline recheck) must still show the decision-time role
105	// order, complete matched list, effect, reason and actual version.
106	func TestDecideListCopiesSurviveCallerEdits(t *testing.T) {
107		s := NewStore()
108		if _, err := s.Publish("acme", 0, listIsolationPolicies()); err != nil {
109			t.Fatal(err)
110		}
111		roles := listIsolationRoles()
112		allowReq := roleRequest("u2", roles)
113		denyReq := roleRequest("u1", roles)
114	
115		allowD := s.Decide("acme", allowReq) // seq 2, allowed
116		denyD := s.Decide("acme", denyReq)   // seq 3, denied with matches
117		if !allowD.Allowed || allowD.Version != 1 || len(allowD.Matched) != 1 {
118			t.Fatalf("setup allow decision = %+v", allowD)
119		}
120		if denyD.Allowed || denyD.Reason != "matched deny policy" ||
121			denyD.Version != 1 || len(denyD.Matched) != 3 {
122			t.Fatalf("setup deny decision = %+v, want a denial carrying 3 matches", denyD)
123		}
124		// Snapshot what history must remember before the caller edits anything.
125		wantRoles := append([]string(nil), roles...)
126		wantAllow := cloneDecisionValue(allowD)
127		wantDeny := cloneDecisionValue(denyD)
128	
129		// The caller rewrites the request they submitted...
130		allowReq.Subject.Roles[0] = "替换后的角色"
131		allowReq.Subject.Roles = append(allowReq.Subject.Roles, "新增角色")
132		denyReq.Subject.Roles[2] = "被改写的原始字节"
133		denyReq.Subject.Roles = append(denyReq.Subject.Roles, "另一个新增角色")
134		// ...and the returned decisions they hold.
135		allowD.Matched[0] = "forged-policy"
136		allowD.Matched = append(allowD.Matched, "ghost-policy")
137		denyD.Matched[0] = "forged-policy"
138		denyD.Matched = append(denyD.Matched, "ghost-policy")
139	
140		// Full export: stored content is byte-for-byte the decision-time content.
141		recs, cp, err := s.AuditExport("acme", 0)
142		if err != nil {
143			t.Fatal(err)
144		}
145		if len(recs) != 3 {
146			t.Fatalf("records = %d, want 3; reads/edits must not append", len(recs))
147		}
148		if err := VerifyAudit("acme", recs, cp); err != nil {
149			t.Fatalf("stored chain changed through caller list edits: %v", err)
150		}
151		assertDecisionListContent(t, &recs[1], 2, wantRoles, wantAllow)
152		assertDecisionListContent(t, &recs[2], 3, wantRoles, wantDeny)
153	
154		// Paged query returns the same content.
155		paged := drainAudit(t, s, "acme", AuditDecision, "")
156		if len(paged) != 2 {
157			t.Fatalf("paged decisions = %d, want 2", len(paged))
158		}
159		assertDecisionListContent(t, recordBySeq(t, paged, 2), 2, wantRoles, wantAllow)
160		assertDecisionListContent(t, recordBySeq(t, paged, 3), 3, wantRoles, wantDeny)
161	
162		// Replaying by the stored record still reaches the original conclusion.
163		gotAllow, err := s.RecheckDecision("acme", 2)
164		if err != nil || !reflect.DeepEqual(gotAllow, wantAllow) {
165			t.Fatalf("online allow recheck = %+v, %v, want %+v", gotAllow, err, wantAllow)
166		}
167		gotDeny, err := s.RecheckDecision("acme", 3)
168		if err != nil || !reflect.DeepEqual(gotDeny, wantDeny) {
169			t.Fatalf("online deny recheck = %+v, %v, want %+v", gotDeny, err, wantDeny)
170		}
171	
172		for _, seq := range []int{2, 3} {
173			review, err := RecheckDecisionOffline("acme", recs, cp, seq)
174			if err != nil {
175				t.Fatalf("seq %d offline review: %v", seq, err)
176			}
177			if !review.Consistent {
178				t.Fatalf("seq %d review inconsistent: %+v", seq, review)
179			}
180		}
181		if rv := mustOfflineReview(t, recs, cp, 2); !reflect.DeepEqual(rv.Original, wantAllow) ||
182			!reflect.DeepEqual(rv.Recomputed, wantAllow) {
183			t.Fatalf("allow offline review = %+v, want %+v", rv, wantAllow)
184		}
185		if rv := mustOfflineReview(t, recs, cp, 3); !reflect.DeepEqual(rv.Original, wantDeny) ||
186			!reflect.DeepEqual(rv.Recomputed, wantDeny) {
187			t.Fatalf("deny offline review = %+v, want %+v", rv, wantDeny)
188		}
189	}
190	
191	// mustOfflineReview runs RecheckDecisionOffline, failing on error.
192	func mustOfflineReview(t *testing.T, recs []AuditRecord, cp Checkpoint, seq int) OfflineDecisionReview {
193		t.Helper()
194		rv, err := RecheckDecisionOffline("acme", recs, cp, seq)
195		if err != nil {
196			t.Fatalf("offline review seq %d: %v", seq, err)
197		}
198		return rv
199	}
200	
201	// TestReadMaterialListEditsStayWithCaller edits the roles and matched
202	// lists in material obtained three different ways — the first query page,
203	// a later paged page, and a complete export. Each edit must change only
204	// that copy: another read and the copy retained earlier keep the original
205	// content, a fresh full export still verifies against the original
206	// checkpoint, and per-record rechecks still reach the original
207	// conclusions. A full export whose list content was edited must fail the
208	// original checkpoint with the existing ErrInvalidRange. None of these
209	// operations appends an audit record.
210	func TestReadMaterialListEditsStayWithCaller(t *testing.T) {
211		s := NewStore()
212		if _, err := s.Publish("acme", 0, listIsolationPolicies()); err != nil { // seq 1, v1
213			t.Fatal(err)
214		}
215		roles := listIsolationRoles()
216		allowReq := roleRequest("u2", roles)
217		allowD := s.Decide("acme", allowReq) // seq 2, v1 allow
218		wantAllow := cloneDecisionValue(allowD)
219		if _, err := s.Publish("acme", 1, listIsolationPolicies()); err != nil { // seq 3, v2
220			t.Fatal(err)
221		}
222		denyReq := roleRequest("u1", roles)
223		denyD := s.Decide("acme", denyReq) // seq 4, v2 deny with matches
224		wantDeny := cloneDecisionValue(denyD)
225		s.Decide("acme", request("acme", "u9", "r1", "org/a", "read")) // seq 5, no match
226	
227		// A complete copy and the checkpoint retained before any caller edit.
228		retained, cp, err := s.AuditExport("acme", 0)
229		if err != nil {
230			t.Fatal(err)
231		}
232		if err := VerifyAudit("acme", retained, cp); err != nil {
233			t.Fatalf("retained material must verify: %v", err)
234		}
235		wantRoles := append([]string(nil), roles...)
236	
237		// Edit the record inside the FIRST query page.
238		page1, err := s.AuditQuery("acme", 1, 2, "", "")
239		if err != nil {
240			t.Fatal(err)
241		}
242		if len(page1.Records) != 2 || page1.Records[1].Seq != 2 {
243			t.Fatalf("first page layout = %+v", page1.Records)
244		}
245		rewriteLists(&page1.Records[1])
246	
247		// Edit the record inside a LATER page.
248		page2, err := s.AuditPage(page1.Checkpoint, page1.Next, 2, "", "")
249		if err != nil {
250			t.Fatal(err)
251		}
252		page3, err := s.AuditPage(page2.Checkpoint, page2.Next, 2, "", "")
253		if err != nil {
254			t.Fatal(err)
255		}
256		if page3.Next != 0 || len(page3.Records) != 1 || page3.Records[0].Seq != 5 {
257			t.Fatalf("paging did not exhaust as expected: page2=%+v page3=%+v", page2, page3)
258		}
259		rewriteLists(recordBySeq(t, page2.Records, 4))
260	
261		// Edit a complete export copy.
262		mine, _, err := s.AuditExport("acme", 0)
263		if err != nil {
264			t.Fatal(err)
265		}
266		rewriteLists(recordBySeq(t, mine, 2))
267		rewriteLists(recordBySeq(t, mine, 4))
268	
269		// A full export whose list content was edited cannot pass the original
270		// checkpoint, and offline review must refuse it rather than review
271		// tampered history.
272		tampered := cloneExportedRecords(retained)
273		rewriteLists(recordBySeq(t, tampered, 2))
274		rewriteLists(recordBySeq(t, tampered, 4))
275		if err := VerifyAudit("acme", tampered, cp); !errors.Is(err, ErrInvalidRange) {
276			t.Fatalf("tampered export verify err = %v, want ErrInvalidRange", err)
277		}
278		for _, seq := range []int{2, 4} {
279			if rv, err := RecheckDecisionOffline("acme", tampered, cp, seq); !errors.Is(err, ErrInvalidRange) {
280				t.Fatalf("tampered offline review seq %d = %+v, %v, want ErrInvalidRange", seq, rv, err)
281			}
282		}
283	
284		// A fresh read still shows decision-time content...
285		fresh, freshCP, err := s.AuditExport("acme", 0)
286		if err != nil {
287			t.Fatal(err)
288		}
289		if freshCP != cp {
290			t.Fatalf("checkpoint changed after caller edits: %+v vs %+v", freshCP, cp)
291		}
292		if err := VerifyAudit("acme", fresh, cp); err != nil {
293			t.Fatalf("fresh export fails the original checkpoint: %v", err)
294		}
295		// ...the previously retained copy is untouched...
296		if !reflect.DeepEqual(fresh, retained) {
297			t.Fatal("retained material diverged after other copies were edited")
298		}
299		// ...and a fresh paged query agrees as well.
300		if got := drainAudit(t, s, "acme", "", ""); !reflect.DeepEqual(got, retained) {
301			t.Fatal("paged query content changed after page copies were edited")
302		}
303		assertDecisionListContent(t, recordBySeq(t, fresh, 2), 2, wantRoles, wantAllow)
304		assertDecisionListContent(t, recordBySeq(t, fresh, 4), 4, wantRoles, wantDeny)
305	
306		// Per-record rechecks still reach the original conclusions.
307		if got, err := s.RecheckDecision("acme", 2); err != nil || !reflect.DeepEqual(got, wantAllow) {
308			t.Fatalf("online recheck seq 2 = %+v, %v, want %+v", got, err, wantAllow)
309		}
310		if got, err := s.RecheckDecision("acme", 4); err != nil || !reflect.DeepEqual(got, wantDeny) {
311			t.Fatalf("online recheck seq 4 = %+v, %v, want %+v", got, err, wantDeny)
312		}
313		if rv := mustOfflineReview(t, fresh, cp, 2); !rv.Consistent ||
314			!reflect.DeepEqual(rv.Original, wantAllow) {
315			t.Fatalf("fresh offline review seq 2 = %+v, want %+v", rv, wantAllow)
316		}
317		if rv := mustOfflineReview(t, fresh, cp, 4); !rv.Consistent ||
318			!reflect.DeepEqual(rv.Original, wantDeny) {
319			t.Fatalf("fresh offline review seq 4 = %+v, want %+v", rv, wantDeny)
320		}
321	
322		// All of the above is read-only: no audit record was appended.
323		if got := len(drainAudit(t, s, "acme", "", "")); got != 5 {
324			t.Fatalf("records = %d, want 5; reads and edits must not append", got)
325		}
326		if v := s.CurrentVersion("acme"); v != 2 {
327			t.Fatalf("current version = %d, want 2", v)
328		}
329	}
330	
331	// rewriteLists simulates the caller editing one record copy: overwrite a
332	// role name and a matched policy name, then append entries to both lists.
333	// Lists must be non-empty, which every target decision carries.
334	func rewriteLists(r *AuditRecord) {
335		roles := r.Decision.Request.Subject.Roles
336		roles[0] = "forged-role"
337		r.Decision.Request.Subject.Roles = append(roles, "ghost-role")
338		matched := r.Decision.Decision.Matched
339		matched[0] = "forged-policy"
340		r.Decision.Decision.Matched = append(matched, "ghost-policy")
341	}
342	
343	// TestEmptyListShapesAndMatchlessDenialsPreserved locks the current
344	// storage shapes for empty lists: a request with no roles (nil) and one
345	// with an explicitly empty role list must not be exchanged for each other
346	// on read, and denials that matched no policy — both the "no matching
347	// allow policy" result (non-nil empty matched list) and an envelope
348	// rejection before policy evaluation (nil matched list, version 0) — must
349	// keep their original result shapes through export, paging and archive.
350	func TestEmptyListShapesAndMatchlessDenialsPreserved(t *testing.T) {
351		s := NewStore()
352		if _, err := s.Publish("acme", 0, nil); err != nil { // v1 denies everything
353			t.Fatal(err)
354		}
355	
356		nilReq := request("acme", "u1", "r1", "org/a", "read") // roles left nil
357		nilDeny := s.Decide("acme", nilReq)                    // seq 2
358		emptyReq := request("acme", "u2", "r1", "org/a", "read")
359		emptyReq.Subject.Roles = []string{}     // explicitly empty
360		emptyDeny := s.Decide("acme", emptyReq) // seq 3
361		disabledReq := request("acme", "u3", "r1", "org/a", "read")
362		disabledReq.Subject.Disabled = true
363		envDeny := s.Decide("acme", disabledReq) // seq 4, envelope rejection
364	
365		for _, d := range []Decision{nilDeny, emptyDeny} {
366			if d.Allowed || d.Reason != "no matching allow policy" || d.Version != 1 || len(d.Matched) != 0 {
367				t.Fatalf("setup policy denial = %+v", d)
368			}
369		}
370		if envDeny.Allowed || envDeny.Reason != "subject is disabled" || envDeny.Version != 0 || envDeny.Matched != nil {
371			t.Fatalf("setup envelope denial = %+v, want nil matched, version 0", envDeny)
372		}
373	
374		// A late edit of the caller's explicitly-empty slice must not matter.
375		emptyReq.Subject.Roles = append(emptyReq.Subject.Roles, "late-role")
376	
377		recs, cp, err := s.AuditExport("acme", 0)
378		if err != nil {
379			t.Fatal(err)
380		}
381		if err := VerifyAudit("acme", recs, cp); err != nil {
382			t.Fatalf("empty-list chain: %v", err)
383		}
384		nilRec := recordBySeq(t, recs, 2)
385		emptyRec := recordBySeq(t, recs, 3)
386		envRec := recordBySeq(t, recs, 4)
387	
388		if nilRec.Decision.Request.Subject.Roles != nil {
389			t.Fatalf("nil roles read back as %v", nilRec.Decision.Request.Subject.Roles)
390		}
391		if roles := emptyRec.Decision.Request.Subject.Roles; roles == nil || len(roles) != 0 {
392			t.Fatalf("explicitly empty roles read back as %v", roles)
393		}
394		// The two shapes must not collapse onto one fingerprint.
395		if nilRec.Fingerprint == emptyRec.Fingerprint {
396			t.Fatal("nil roles and empty roles share a fingerprint")
397		}
398		// Policy-evaluation denials carry a non-nil empty matched list; the
399		// envelope rejection carries a nil one. Both are matchless denials.
400		if nilRec.Decision.Decision.Matched == nil || emptyRec.Decision.Decision.Matched == nil {
401			t.Fatal("no-match denial must keep its non-nil empty matched list")
402		}
403		if envRec.Decision.Decision.Matched != nil {
404			t.Fatal("envelope rejection matched list must stay nil")
405		}
406		if !reflect.DeepEqual(nilRec.Decision.Decision, cloneDecisionValue(nilDeny)) {
407			t.Fatalf("nil-roles denial not preserved: %+v", nilRec.Decision.Decision)
408		}
409		if !reflect.DeepEqual(emptyRec.Decision.Decision, cloneDecisionValue(emptyDeny)) {
410			t.Fatalf("empty-roles denial not preserved: %+v", emptyRec.Decision.Decision)
411		}
412	
413		// The paged query keeps the same shapes.
414		paged := drainAudit(t, s, "acme", AuditDecision, "")
415		if got := recordBySeq(t, paged, 2).Decision.Request.Subject.Roles; got != nil {
416			t.Fatalf("paged query turned nil roles into %v", got)
417		}
418		if got := recordBySeq(t, paged, 3).Decision.Request.Subject.Roles; got == nil || len(got) != 0 {
419			t.Fatalf("paged query turned empty roles into %v", got)
420		}
421	
422		// The archive round trip keeps the same shapes and still verifies.
423		archive, err := EncodeAuditArchive("acme", recs, cp)
424		if err != nil {
425			t.Fatal(err)
426		}
427		decoded, err := DecodeAuditArchive(archive, "acme", cp)
428		if err != nil {
429			t.Fatalf("archive decode: %v", err)
430		}
431		if !reflect.DeepEqual(decoded, recs) {
432			t.Fatal("archive round trip changed empty-list shapes")
433		}
434		if err := VerifyAudit("acme", decoded, cp); err != nil {
435			t.Fatalf("decoded empty-list chain: %v", err)
436		}
437	
438		// Every matchless denial re-reviews to the original conclusion.
439		for seq, want := range map[int]Decision{2: nilDeny, 3: emptyDeny, 4: envDeny} {
440			if got, err := s.RecheckDecision("acme", seq); err != nil || !decisionsEqual(got, want) {
441				t.Fatalf("online recheck seq %d = %+v, %v, want %+v", seq, got, err, want)
442			}
443			if rv := mustOfflineReview(t, recs, cp, seq); !rv.Consistent {
444				t.Fatalf("matchless denial seq %d review inconsistent: %+v", seq, rv)
445			}
446		}
447	}
448	
449	// TestNonEmptyListsPreserveChineseSpacesAndRawBytes checks the byte-level
450	// content guarantee on non-empty lists: Chinese, spaces and non-UTF-8
451	// bytes in roles and matched policy ids survive as the original bytes,
452	// even after the caller edits the request, the returned decision and
453	// later read copies. The full export keeps passing its chain check,
454	// including through an archive round trip.
455	func TestNonEmptyListsPreserveChineseSpacesAndRawBytes(t *testing.T) {
456		s := NewStore()
457		policies := []Policy{
458			// Allow hit with spaces and Chinese; deny hit carrying a different
459			// invalid byte than the request does, so matched ordering exercises
460			// raw content too.
461			{ID: "通 行 策 略", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
462			{ID: "拒" + anotherInvalidByte + "止 策 略", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectDeny},
463			{ID: "允 许" + invalidByte + "策 略", Subject: "u2", Action: "read", Scope: "org/a", Effect: EffectAllow},
464		}
465		if _, err := s.Publish("acme", 0, policies); err != nil {
466			t.Fatal(err)
467		}
468		roles := listIsolationRoles()
469		allowReq := roleRequest("u2", roles)
470		denyReq := roleRequest("u1", roles)
471		allowD := s.Decide("acme", allowReq) // seq 2
472		denyD := s.Decide("acme", denyReq)   // seq 3
473		if !allowD.Allowed || denyD.Allowed {
474			t.Fatalf("setup decisions: allow=%+v deny=%+v", allowD, denyD)
475		}
476		if !strings.Contains(allowD.Matched[0], invalidByte) {
477			t.Fatal("test premise broken: allow hit must carry the invalid byte")
478		}
479		if !strings.Contains(denyD.Matched[0], anotherInvalidByte) {
480			t.Fatal("test premise broken: deny hit must carry the other invalid byte")
481		}
482		wantRoles := append([]string(nil), roles...)
483		wantAllow := cloneDecisionValue(allowD)
484		wantDeny := cloneDecisionValue(denyD)
485	
486		// Caller edits the submitted request lists and the returned decisions.
487		allowReq.Subject.Roles[0] = "plain replacement"
488		allowReq.Subject.Roles = append(allowReq.Subject.Roles, "尾随角色")
489		denyReq.Subject.Roles[2] = "\xfe"
490		denyReq.Subject.Roles = append(denyReq.Subject.Roles, "x")
491		allowD.Matched[0] = "plain"
492		allowD.Matched = append(allowD.Matched, "ghost")
493		denyD.Matched[0] = "plain"
494		denyD.Matched = append(denyD.Matched, "ghost")
495	
496		recs, cp, err := s.AuditExport("acme", 0)
497		if err != nil {
498			t.Fatal(err)
499		}
500		if err := VerifyAudit("acme", recs, cp); err != nil {
501			t.Fatalf("raw-byte chain after caller edits: %v", err)
502		}
503		assertDecisionListContent(t, &recs[1], 2, wantRoles, wantAllow)
504		assertDecisionListContent(t, &recs[2], 3, wantRoles, wantDeny)
505		savedRoles := recs[1].Decision.Request.Subject.Roles
506		if !strings.Contains(savedRoles[0], "角色") ||
507			!strings.HasPrefix(savedRoles[1], "  ") || !strings.HasSuffix(savedRoles[1], "  ") ||
508			!strings.Contains(savedRoles[2], invalidByte) {
509			t.Fatalf("roles lost their original bytes/spacing/order: %q", savedRoles)
510		}
511		if !strings.Contains(recordBySeq(t, recs, 2).Decision.Decision.Matched[0], invalidByte) {
512			t.Fatal("stored allow matched list lost its invalid byte")
513		}
514		if !strings.Contains(recordBySeq(t, recs, 3).Decision.Decision.Matched[0], anotherInvalidByte) {
515			t.Fatal("stored deny matched list lost its invalid byte")
516		}
517	
518		// Editing the exported copy and reading again leaves the stored bytes
519		// intact and the chain check still holds on the fresh read.
520		rewriteLists(&recs[1])
521		rewriteLists(&recs[2])
522		fresh, freshCP, err := s.AuditExport("acme", 0)
523		if err != nil {
524			t.Fatal(err)
525		}
526		if freshCP != cp {
527			t.Fatal("checkpoint changed despite list edits")
528		}
529		if err := VerifyAudit("acme", fresh, cp); err != nil {
530			t.Fatalf("fresh raw-byte export must still verify: %v", err)
531		}
532		assertDecisionListContent(t, &fresh[1], 2, wantRoles, wantAllow)
533		assertDecisionListContent(t, &fresh[2], 3, wantRoles, wantDeny)
534	
535		// Paged query bytes agree with the export's decision records.
536		if got := drainAudit(t, s, "acme", AuditDecision, ""); !reflect.DeepEqual(got, fresh[1:]) {
537			t.Fatal("paged raw-byte content differs from the export")
538		}
539	
540		// The archive preserves the exact bytes offline and stays verifiable.
541		archive, err := EncodeAuditArchive("acme", fresh, cp)
542		if err != nil {
543			t.Fatal(err)
544		}
545		decoded, err := DecodeAuditArchive(archive, "acme", cp)
546		if err != nil {
547			t.Fatalf("raw-byte archive decode: %v", err)
548		}
549		if !reflect.DeepEqual(decoded, fresh) {
550			t.Fatal("raw-byte archive round trip changed list content")
551		}
552	
553		// Offline re-computation derives matched policy ids with the same raw
554		// bytes and agrees with the preserved originals.
555		allowReview := mustOfflineReview(t, decoded, cp, 2)
556		if !allowReview.Consistent || !reflect.DeepEqual(allowReview.Original, wantAllow) {
557			t.Fatalf("raw-byte allow review = %+v, want %+v", allowReview, wantAllow)
558		}
559		if !strings.Contains(allowReview.Recomputed.Matched[0], invalidByte) {
560			t.Fatal("offline recomputation normalized the allow matched id")
561		}
562		denyReview := mustOfflineReview(t, decoded, cp, 3)
563		if !denyReview.Consistent || !reflect.DeepEqual(denyReview.Original, wantDeny) {
564			t.Fatalf("raw-byte deny review = %+v, want %+v", denyReview, wantDeny)
565		}
566		if !strings.Contains(denyReview.Recomputed.Matched[0], anotherInvalidByte) {
567			t.Fatal("offline recomputation normalized the deny matched id")
568		}
569	
570		// Nothing here appended records.
571		if got := len(drainAudit(t, s, "acme", "", "")); got != 3 {
572			t.Fatalf("records = %d, want 3; reads and edits must not append", got)
573		}
574	}
575	
576	// capaciousEmptyRoles returns a NON-NIL role list with no elements but spare
577	// capacity. It is the shape that exposed the isolation bug: cloning lists
578	// only when len > 0 let this list's backing array be shared between the
579	// stored record, every query/page/export copy and the caller's own slice, so
580	// appending a role to one handed-out copy overwrote the first role slot of
581	// every other copy.
582	func capaciousEmptyRoles() []string {
583		return make([]string, 0, 4)
584	}
585	
586	// requireNonNilEmptyRoles fails unless the role list is a non-nil, empty
587	// slice — the shape that must stay distinct from nil.
588	func requireNonNilEmptyRoles(t *testing.T, label string, roles []string) {
589		t.Helper()
590		if roles == nil || len(roles) != 0 {
591			t.Fatalf("%s roles = %v, want non-nil empty", label, roles)
592		}
593	}
594	
595	// TestEmptyRoleListWithCapacityIsolated is the regression for capacious
596	// empty role lists. A subject completes an allow, a no-match denial and a
597	// disabled-subject envelope denial, each with a non-nil empty role list that
598	// still has spare capacity. The caller obtains audit material two at a time
599	// from the first query, a later page and a full export, and appends a
600	// distinct temporary role to each copy; appending to one result must never
601	// overwrite another's role, and appending to the originally submitted list
602	// must reach no material. A fresh read still shows a non-nil empty list with
603	// the unchanged decision (allowed, reason, matched policies, version); nil
604	// roles stay nil. Checkpoints and fingerprints are unchanged by the fix, the
605	// material still verifies, archives, reads back and reviews offline.
606	func TestEmptyRoleListWithCapacityIsolated(t *testing.T) {
607		s := NewStore()
608		policies := []Policy{{ID: "p-allow", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow}}
609		if _, err := s.Publish("acme", 0, policies); err != nil { // seq 1, v1
610			t.Fatal(err)
611		}
612	
613		allowReq := request("acme", "u1", "r1", "org/a", "read")
614		allowReq.Subject.Roles = capaciousEmptyRoles()
615		denyReq := request("acme", "u9", "r1", "org/a", "read")
616		denyReq.Subject.Roles = capaciousEmptyRoles()
617		disabledReq := request("acme", "u3", "r1", "org/a", "read")
618		disabledReq.Subject.Roles = capaciousEmptyRoles()
619		disabledReq.Subject.Disabled = true
620	
621		allowD := s.Decide("acme", allowReq)     // seq 2, allowed
622		denyD := s.Decide("acme", denyReq)       // seq 3, no-match denial
623		envDeny := s.Decide("acme", disabledReq) // seq 4, envelope denial
624		if !allowD.Allowed || allowD.Version != 1 || !reflect.DeepEqual(allowD.Matched, []string{"p-allow"}) {
625			t.Fatalf("setup allow = %+v", allowD)
626		}
627		if denyD.Allowed || denyD.Reason != "no matching allow policy" || denyD.Version != 1 || denyD.Matched == nil {
628			t.Fatalf("setup no-match denial = %+v, want non-nil empty matched", denyD)
629		}
630		if envDeny.Allowed || envDeny.Reason != "subject is disabled" || envDeny.Version != 0 || envDeny.Matched != nil {
631			t.Fatalf("setup envelope denial = %+v, want nil matched, version 0", envDeny)
632		}
633		want := map[int]Decision{
634			2: cloneDecisionValue(allowD),
635			3: cloneDecisionValue(denyD),
636			4: cloneDecisionValue(envDeny),
637		}
638	
639		// The caller later appends to the lists it submitted; no audit material
640		// may observe that.
641		allowReq.Subject.Roles = append(allowReq.Subject.Roles, "caller-allow-role")
642		denyReq.Subject.Roles = append(denyReq.Subject.Roles, "caller-deny-role")
643		disabledReq.Subject.Roles = append(disabledReq.Subject.Roles, "caller-disabled-role")
644	
645		exportA, cp, err := s.AuditExport("acme", 0)
646		if err != nil {
647			t.Fatal(err)
648		}
649		exportB, _, err := s.AuditExport("acme", 0)
650		if err != nil {
651			t.Fatal(err)
652		}
653		if err := VerifyAudit("acme", exportA, cp); err != nil {
654			t.Fatalf("export chain: %v", err)
655		}
656	
657		// Page by decision kind: seq 1 is the publish (filtered out), so a
658		// pageSize of 1 puts only seq 2 on the first page and seq 3, 4 on the
659		// later page.
660		pageA, err := s.AuditQuery("acme", 1, 1, AuditDecision, "")
661		if err != nil {
662			t.Fatal(err)
663		}
664		pageB, err := s.AuditPage(pageA.Checkpoint, pageA.Next, 2, AuditDecision, "")
665		if err != nil {
666			t.Fatal(err)
667		}
668		if len(pageA.Records) != 1 || pageA.Records[0].Seq != 2 {
669			t.Fatalf("first query page layout = %+v", pageA.Records)
670		}
671		if len(pageB.Records) != 2 || pageB.Records[0].Seq != 3 || pageB.Records[1].Seq != 4 || pageB.Next != 0 {
672			t.Fatalf("later page layout = %+v next=%d", pageB.Records, pageB.Next)
673		}
674	
675		// Every read shows a non-nil empty role list.
676		for _, seq := range []int{2, 3, 4} {
677			requireNonNilEmptyRoles(t, "exportA", recordBySeq(t, exportA, seq).Decision.Request.Subject.Roles)
678			requireNonNilEmptyRoles(t, "exportB", recordBySeq(t, exportB, seq).Decision.Request.Subject.Roles)
679		}
680		requireNonNilEmptyRoles(t, "query seq2", pageA.Records[0].Decision.Request.Subject.Roles)
681		requireNonNilEmptyRoles(t, "page seq3", pageB.Records[0].Decision.Request.Subject.Roles)
682		requireNonNilEmptyRoles(t, "page seq4", pageB.Records[1].Decision.Request.Subject.Roles)
683	
684		// Append a distinct temporary role to the same decision in two export
685		// copies. A shared backing array makes the second append overwrite the
686		// first — exactly the reported defect.
687		aRoles := recordBySeq(t, exportA, 2).Decision.Request.Subject.Roles
688		bRoles := recordBySeq(t, exportB, 2).Decision.Request.Subject.Roles
689		aRoles = append(aRoles, "临时角色甲")
690		bRoles = append(bRoles, "临时角色乙")
691		// Assign back: append may or may not reuse the slice header, but the
692		// record copy must be the one the caller is editing.
693		recordBySeq(t, exportA, 2).Decision.Request.Subject.Roles = aRoles
694		recordBySeq(t, exportB, 2).Decision.Request.Subject.Roles = bRoles
695		if got := recordBySeq(t, exportA, 2).Decision.Request.Subject.Roles; !reflect.DeepEqual(got, []string{"临时角色甲"}) {
696			t.Fatalf("export A seq2 roles = %q, want [临时角色甲]", got)
697		}
698		if got := recordBySeq(t, exportB, 2).Decision.Request.Subject.Roles; !reflect.DeepEqual(got, []string{"临时角色乙"}) {
699			t.Fatalf("export B seq2 roles = %q, want [临时角色乙]; read copies shared storage", got)
700		}
701	
702		// Query page and later page each get their own appendable copy.
703		pageA.Records[0].Decision.Request.Subject.Roles = append(pageA.Records[0].Decision.Request.Subject.Roles, "query-role")
704		pageB.Records[0].Decision.Request.Subject.Roles = append(pageB.Records[0].Decision.Request.Subject.Roles, "page-deny-role")
705		pageB.Records[1].Decision.Request.Subject.Roles = append(pageB.Records[1].Decision.Request.Subject.Roles, "page-disabled-role")
706	
707		// Cross-read isolation: an edit anywhere is invisible to every other
708		// read of the same sequence, and the caller's post-hoc appends never
709		// appear.
710		untouched := []struct {
711			label string
712			roles []string
713		}{
714			{"exportA seq3", recordBySeq(t, exportA, 3).Decision.Request.Subject.Roles},
715			{"exportA seq4", recordBySeq(t, exportA, 4).Decision.Request.Subject.Roles},
716			{"exportB seq3", recordBySeq(t, exportB, 3).Decision.Request.Subject.Roles},
717			{"exportB seq4", recordBySeq(t, exportB, 4).Decision.Request.Subject.Roles},
718			{"query seq2", pageA.Records[0].Decision.Request.Subject.Roles},
719			{"page seq3", pageB.Records[0].Decision.Request.Subject.Roles},
720			{"page seq4", pageB.Records[1].Decision.Request.Subject.Roles},
721		}
722		for i, c := range untouched {
723			var leaked bool
724			switch {
725			case i <= 3:
726				leaked = c.roles == nil || len(c.roles) != 0
727			default:
728				leaked = len(c.roles) != 1
729			}
730			if leaked {
731				t.Fatalf("%s roles = %q, other copies' edits leaked across reads", c.label, c.roles)
732			}
733		}
734		for name, recs := range map[string][]AuditRecord{"exportA": exportA, "exportB": exportB} {
735			for _, seq := range []int{2, 3, 4} {
736				for _, got := range recordBySeq(t, recs, seq).Decision.Request.Subject.Roles {
737					if strings.HasPrefix(got, "caller-") {
738						t.Fatalf("%s seq %d leaked the caller's post-hoc role %q", name, seq, got)
739					}
740				}
741			}
742		}
743	
744		// A fresh read after all edits still shows non-nil empty lists, the same
745		// checkpoint and the unchanged decision content.
746		fresh, freshCP, err := s.AuditExport("acme", 0)
747		if err != nil {
748			t.Fatal(err)
749		}
750		if freshCP != cp {
751			t.Fatalf("checkpoint changed after caller edits: %+v vs %+v", freshCP, cp)
752		}
753		if err := VerifyAudit("acme", fresh, cp); err != nil {
754			t.Fatalf("fresh export fails original checkpoint: %v", err)
755		}
756		for _, seq := range []int{2, 3, 4} {
757			r := recordBySeq(t, fresh, seq)
758			requireNonNilEmptyRoles(t, "fresh", r.Decision.Request.Subject.Roles)
759			if !decisionsEqual(r.Decision.Decision, want[seq]) {
760				t.Fatalf("fresh seq %d decision = %+v, want %+v", seq, r.Decision.Decision, want[seq])
761			}
762			if got, err := s.RecheckDecision("acme", seq); err != nil || !decisionsEqual(got, want[seq]) {
763				t.Fatalf("online recheck seq %d = %+v, %v", seq, got, err)
764			}
765			if rv, err := RecheckDecisionOffline("acme", fresh, cp, seq); err != nil || !rv.Consistent {
766				t.Fatalf("offline review seq %d = %+v, %v", seq, rv, err)
767			}
768		}
769		// Offline review on role-edited material must refuse it: roles are part
770		// of the fingerprint, so that copy is tampered material and fails the
771		// whole-material chain check with ErrInvalidRange (never silently
772		// reviewed). The store's own history is unaffected.
773		if _, err := RecheckDecisionOffline("acme", exportB, cp, 2); !errors.Is(err, ErrInvalidRange) {
774			t.Fatalf("offline review of role-edited material err = %v, want ErrInvalidRange", err)
775		}
776	
777		// Archive round trip preserves the non-nil empty shape and each decode is
778		// an independent copy.
779		archive, err := EncodeAuditArchive("acme", fresh, cp)
780		if err != nil {
781			t.Fatal(err)
782		}
783		d1, err := DecodeAuditArchive(archive, "acme", cp)
784		if err != nil {
785			t.Fatalf("decode 1: %v", err)
786		}
787		d2, err := DecodeAuditArchive(archive, "acme", cp)
788		if err != nil {
789			t.Fatalf("decode 2: %v", err)
790		}
791		for _, seq := range []int{2, 3, 4} {
792			requireNonNilEmptyRoles(t, "archive d1", recordBySeq(t, d1, seq).Decision.Request.Subject.Roles)
793			requireNonNilEmptyRoles(t, "archive d2", recordBySeq(t, d2, seq).Decision.Request.Subject.Roles)
794		}
795		recordBySeq(t, d1, 2).Decision.Request.Subject.Roles = append(recordBySeq(t, d1, 2).Decision.Request.Subject.Roles, "归档角色甲")
796		recordBySeq(t, d2, 2).Decision.Request.Subject.Roles = append(recordBySeq(t, d2, 2).Decision.Request.Subject.Roles, "归档角色乙")
797		if got := recordBySeq(t, d1, 2).Decision.Request.Subject.Roles; !reflect.DeepEqual(got, []string{"归档角色甲"}) {
798			t.Fatalf("archive d1 roles = %q", got)
799		}
800		if got := recordBySeq(t, d2, 2).Decision.Request.Subject.Roles; !reflect.DeepEqual(got, []string{"归档角色乙"}) {
801			t.Fatalf("archive d2 roles = %q; decodes shared storage", got)
802		}
803	
804		// nil roles stay genuinely nil and never collapse to empty.
805		nilReq := request("acme", "u7", "r1", "org/a", "read") // roles left nil
806		s.Decide("acme", nilReq)                               // seq 5
807		nilExport, _, err := s.AuditExport("acme", 0)
808		if err != nil {
809			t.Fatal(err)
810		}
811		if got := recordBySeq(t, nilExport, 5).Decision.Request.Subject.Roles; got != nil {
812			t.Fatalf("nil roles read back as %v", got)
813		}
814	
815		// Reads and caller edits appended nothing and changed no version.
816		if got := len(drainAudit(t, s, "acme", "", "")); got != 5 {
817			t.Fatalf("records = %d, want 5", got)
818		}
819		if v := s.CurrentVersion("acme"); v != 1 {
820			t.Fatalf("current version = %d, want 1", v)
821		}
822	}
